'use strict';

const fs = require('fs');

const n = Number(fs.readFileSync(0, 'utf8').trim());
const MOD = 998244353n;

function zeroMatrix(size) {
    return Array.from({ length: size }, () => Array(size).fill(0n));
}

function multiply(a, b) {
    const size = a.length;
    const c = zeroMatrix(size);

    for (let i = 0; i < size; i++) {
        for (let k = 0; k < size; k++) {
            if (a[i][k] === 0n) continue;
            for (let j = 0; j < size; j++) {
                if (b[k][j] === 0n) continue;
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    return c;
}

function matrixPower(base, exponent) {
    const size = base.length;
    let result = zeroMatrix(size);

    for (let i = 0; i < size; i++) result[i][i] = 1n;

    while (exponent > 0) {
        if (exponent & 1) result = multiply(result, base);
        base = multiply(base, base);
        exponent = Math.floor(exponent / 2);
    }
    return result;
}

function trace(matrix) {
    let result = 0n;
    for (let i = 0; i < matrix.length; i++) {
        result += matrix[i][i];
        if (result >= MOD) result -= MOD;
    }
    return result;
}

const A = [
    [1n, 0n, 0n],
    [1n, 1n, 0n],
    [1n, 2n, 1n]
];

const B = [
    [0n, 0n, 1n],
    [0n, 0n, 0n],
    [0n, 0n, 0n]
];

const SIZE = 12;
const transfer = zeroMatrix(SIZE);
const noMonomer = zeroMatrix(4);

function addBlock(fromMask, toMask, block) {
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            const row = fromMask * 3 + i;
            const col = toMask * 3 + j;
            transfer[row][col] =
                (transfer[row][col] + block[i][j]) % MOD;
        }
    }
}

function addNoMonomer(from, to) {
    noMonomer[from][to]++;
    if (noMonomer[from][to] >= MOD) noMonomer[from][to] -= MOD;
}

for (let mask = 0; mask < 4; mask++) {
    if (mask & 1) {
        const next = mask >> 1;
        addBlock(mask, next, A);
        addNoMonomer(mask, next);
    } else {
        const shifted = mask >> 1;

        addBlock(mask, shifted, B);

        if ((mask & 2) === 0) {
            const next = shifted | 1;
            addBlock(mask, next, A);
            addNoMonomer(mask, next);
        }

        {
            const next = shifted | 2;
            addBlock(mask, next, A);
            addNoMonomer(mask, next);
        }
    }
}

const total = trace(matrixPower(transfer, n));
const withoutDiameters = trace(matrixPower(noMonomer, n));

let answer = (total - 3n * withoutDiameters) % MOD;
if (answer < 0n) answer += MOD;

console.log(answer.toString());

